DO $$ BEGIN CREATE TYPE user_role AS ENUM ('admin','dispatcher','driver','customer'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE order_status AS ENUM ('pending','assigned','picked_up','in_transit','delivered','failed','cancelled'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS organizations (id uuid PRIMARY KEY, name text NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Kolkata', created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO organizations(id,name,timezone) VALUES('00000000-0000-0000-0000-000000000001','RoutePulse','Asia/Kolkata') ON CONFLICT(id) DO NOTHING;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), email citext NOT NULL, name text NOT NULL, role user_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,email));
CREATE TABLE IF NOT EXISTS drivers (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), user_id uuid NOT NULL UNIQUE REFERENCES users(id), status text NOT NULL CHECK(status IN ('available','busy','offline')), capacity_kg numeric(9,2) NOT NULL CHECK(capacity_kg>0), current_lat double precision, current_lng double precision, last_seen_at timestamptz);
ALTER TABLE drivers ADD COLUMN IF NOT EXISTS shift_start text;
ALTER TABLE drivers ADD COLUMN IF NOT EXISTS shift_end text;
ALTER TABLE drivers ADD COLUMN IF NOT EXISTS vehicle_plate text;
ALTER TABLE drivers ADD COLUMN IF NOT EXISTS maintenance_due_at timestamptz;
ALTER TABLE drivers ADD COLUMN IF NOT EXISTS maintenance_status text NOT NULL DEFAULT 'ok' CHECK(maintenance_status IN ('ok','due','overdue'));
CREATE TABLE IF NOT EXISTS orders (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), tracking_code text NOT NULL UNIQUE, customer_name text NOT NULL, customer_email citext NOT NULL, pickup jsonb NOT NULL, dropoff jsonb NOT NULL, package_weight_kg numeric(9,2) NOT NULL CHECK(package_weight_kg>0), priority text NOT NULL CHECK(priority IN ('standard','express','urgent')), status order_status NOT NULL DEFAULT 'pending', amount_minor bigint NOT NULL CHECK(amount_minor>=0), currency char(3) NOT NULL, payment_status text NOT NULL DEFAULT 'unpaid', assigned_driver_id uuid REFERENCES drivers(id), promised_at timestamptz NOT NULL, delivered_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS orders_tenant_status_created_idx ON orders(organization_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS orders_driver_status_idx ON orders(assigned_driver_id,status);
CREATE TABLE IF NOT EXISTS order_events (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), order_id uuid NOT NULL REFERENCES orders(id) ON DELETE CASCADE, type text NOT NULL, message text NOT NULL, actor_id uuid REFERENCES users(id), payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS order_events_order_time_idx ON order_events(order_id,created_at);
CREATE TABLE IF NOT EXISTS outbox_jobs (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), topic text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'pending', attempts int NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS outbox_pending_idx ON outbox_jobs(status,available_at) WHERE status='pending';
CREATE TABLE IF NOT EXISTS payments (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), order_id uuid NOT NULL REFERENCES orders(id), provider text NOT NULL, provider_ref text NOT NULL, amount_minor bigint NOT NULL, currency char(3) NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,provider_ref));
CREATE TABLE IF NOT EXISTS audit_events (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), actor_id uuid REFERENCES users(id), action text NOT NULL, resource_type text NOT NULL, resource_id text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_tenant_time_idx ON audit_events(organization_id,created_at DESC);
ALTER TABLE organizations ADD COLUMN IF NOT EXISTS settings jsonb NOT NULL DEFAULT '{"geofenceRadiusMeters":150,"averageSpeedKph":24,"notificationsEnabled":true}'::jsonb;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS delivery_window_start timestamptz;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS delivery_notes text;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS delivery_pin_hash text;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS parcel_code text;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS reschedule_count integer NOT NULL DEFAULT 0;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS cancelled_at timestamptz;
CREATE UNIQUE INDEX IF NOT EXISTS orders_parcel_code_idx ON orders(parcel_code) WHERE parcel_code IS NOT NULL;
UPDATE orders SET delivery_pin_hash=encode(digest('1234','sha256'),'hex') WHERE delivery_pin_hash IS NULL;
CREATE TABLE IF NOT EXISTS delivery_exceptions (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), order_id uuid NOT NULL REFERENCES orders(id) ON DELETE CASCADE, type text NOT NULL CHECK(type IN ('delay','address_issue','customer_unavailable','vehicle_issue','package_issue','delivery_failed')), description text NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')), created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz, resolution text);
CREATE INDEX IF NOT EXISTS delivery_exceptions_tenant_status_idx ON delivery_exceptions(organization_id,status,created_at DESC);
CREATE TABLE IF NOT EXISTS notification_records (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), user_id uuid REFERENCES users(id), order_id uuid REFERENCES orders(id) ON DELETE CASCADE, channel text NOT NULL CHECK(channel IN ('email','in_app')), title text NOT NULL, message text NOT NULL, status text NOT NULL CHECK(status IN ('queued','sent','simulated','failed')), read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS notifications_tenant_user_time_idx ON notification_records(organization_id,user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS proof_of_delivery (order_id uuid PRIMARY KEY REFERENCES orders(id) ON DELETE CASCADE, organization_id uuid NOT NULL REFERENCES organizations(id), driver_id uuid NOT NULL REFERENCES drivers(id), recipient_name text NOT NULL, signature_data text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS parcel_scans (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), order_id uuid NOT NULL REFERENCES orders(id) ON DELETE CASCADE, parcel_code text NOT NULL, stage text NOT NULL CHECK(stage IN ('pickup','hub','delivery')), scanned_by uuid NOT NULL REFERENCES users(id), scanned_at timestamptz NOT NULL DEFAULT now(), UNIQUE(order_id,stage));
CREATE INDEX IF NOT EXISTS parcel_scans_tenant_time_idx ON parcel_scans(organization_id,scanned_at DESC);
CREATE TABLE IF NOT EXISTS support_tickets (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), order_id uuid REFERENCES orders(id) ON DELETE SET NULL, customer_id uuid REFERENCES users(id) ON DELETE SET NULL, subject text NOT NULL, category text NOT NULL CHECK(category IN ('delivery','payment','address','account','other')), priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high','urgent')), status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','pending','resolved')), created_by uuid NOT NULL REFERENCES users(id), assigned_to uuid REFERENCES users(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS support_tickets_tenant_status_idx ON support_tickets(organization_id,status,updated_at DESC);
CREATE TABLE IF NOT EXISTS support_messages (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), ticket_id uuid NOT NULL REFERENCES support_tickets(id) ON DELETE CASCADE, sender_id uuid NOT NULL REFERENCES users(id), sender_role user_role NOT NULL, message text NOT NULL, internal boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS support_messages_ticket_time_idx ON support_messages(ticket_id,created_at);
